import re

from ollama_service import chat


# =========================================================
# Clean SQL generated by Ollama
# =========================================================

def clean_sql(text: str):

    if not text:
        return ""

    text = text.strip()

    # -----------------------------------------------------
    # Remove markdown code block
    # Example:
    #
    # ```sql
    # SELECT ...
    # ```
    # -----------------------------------------------------

    code_block = re.search(
        r"```(?:sql)?\s*(.*?)```",
        text,
        re.IGNORECASE | re.DOTALL,
    )

    if code_block:
        text = code_block.group(1)

    text = text.strip()


    # -----------------------------------------------------
    # Remove SQL: prefix
    # -----------------------------------------------------

    text = re.sub(
        r"^\s*SQL\s*:\s*",
        "",
        text,
        flags=re.IGNORECASE,
    )


    # -----------------------------------------------------
    # Find SELECT or WITH
    # -----------------------------------------------------

    match = re.search(
        r"\b(SELECT|WITH)\b",
        text,
        re.IGNORECASE,
    )

    if match:
        text = text[match.start():]


    # -----------------------------------------------------
    # Remove text after query if model explains anything
    # -----------------------------------------------------

    text = text.strip()


    return text


# =========================================================
# Generate SQL
# =========================================================

def generate_sql(
    question: str,
    schema_context: str
):

    system_prompt = """
You are an expert SQLite query generator.

Your job is to convert a user's natural-language question
into exactly ONE valid SQLite SELECT query.

IMPORTANT RULES:

1. Use SQLite syntax only.

2. Use ONLY tables provided in the schema.

3. Use ONLY columns provided in the schema.

4. NEVER invent table names.

5. NEVER invent column names.

6. ALWAYS wrap table names in double quotes.

Example:

Correct:
FROM "data_practice"

Incorrect:
FROM data_practice


7. ALWAYS wrap column names in double quotes.

Example:

Correct:
"Actual Price"

Correct:
"JE Code"

Correct:
"Sales Person"

Incorrect:
Actual Price

Incorrect:
JE Code


8. Column names may contain spaces.

You MUST always use double quotes around them.


9. If a numeric column is stored as TEXT,
convert it to REAL before mathematical operations.

For example:

CAST("Actual Price" AS REAL)


10. Use CAST(... AS REAL) for operations such as:

SUM
AVG
MIN
MAX
numeric ORDER BY


11. Example:

SELECT
    "Sales Person",
    SUM(CAST("Actual Price" AS REAL)) AS "Total Actual Price"
FROM "data_practice"
GROUP BY "Sales Person"
ORDER BY "Total Actual Price" DESC
LIMIT 1;


12. If a numeric value may contain commas,
remove commas before converting.

Example:

CAST(
    REPLACE("Actual Price", ',', '')
    AS REAL
)


13. If a numeric value may contain currency symbols,
clean the value before CAST.

Example:

CAST(
    REPLACE(
        REPLACE("Actual Price", ',', ''),
        '₹',
        ''
    )
    AS REAL
)


14. Generate only READ-ONLY queries.

Allowed:

SELECT
WITH ... SELECT


15. NEVER generate:

INSERT
UPDATE
DELETE
DROP
ALTER
CREATE
REPLACE
TRUNCATE
PRAGMA
ATTACH
DETACH
VACUUM


16. Return ONLY SQL.

17. Do NOT return Markdown.

18. Do NOT return explanation.

19. Do NOT return comments.

20. If the user's question cannot be answered
using the given schema, return exactly:

CANNOT_ANSWER
"""


    user_prompt = f"""
DATABASE SCHEMA:

{schema_context}


USER QUESTION:

{question}


Generate exactly one valid SQLite SELECT query.

Important:

- Quote EVERY table name using double quotes.
- Quote EVERY column name using double quotes.
- Never invent a column.
- Never invent a table.
- Use CAST when numeric values are stored as TEXT.
- Return SQL only.
"""


    result = chat(
        [
            {
                "role": "system",
                "content": system_prompt,
            },
            {
                "role": "user",
                "content": user_prompt,
            },
        ],
        temperature=0,
    )


    result = result.strip()


    # -----------------------------------------------------
    # Cannot answer
    # -----------------------------------------------------

    if "CANNOT_ANSWER" in result.upper():

        return "CANNOT_ANSWER"


    # -----------------------------------------------------
    # Clean SQL
    # -----------------------------------------------------

    sql = clean_sql(result)


    print("\n")
    print("=" * 60)
    print("GENERATED SQL")
    print("=" * 60)

    print(sql)

    print("=" * 60)
    print("\n")


    return sql


# =========================================================
# Repair SQL
# =========================================================

def repair_sql(
    question: str,
    schema_context: str,
    previous_sql: str,
    sqlite_error: str,
):

    system_prompt = """
You are an expert SQLite query repair assistant.

You will receive:

1. Database schema
2. User question
3. Failed SQL query
4. SQLite error

Your job is to repair the SQL.

STRICT RULES:

1. Return exactly ONE SQLite query.

2. Query must be read-only.

3. Only SELECT queries are allowed.

4. WITH ... SELECT is allowed.

5. Use ONLY tables provided in the schema.

6. Use ONLY columns provided in the schema.

7. NEVER invent tables.

8. NEVER invent columns.

9. ALWAYS wrap table names in double quotes.

Example:

"data_practice"


10. ALWAYS wrap column names in double quotes.

Example:

"Actual Price"

"JE Code"

"Sales Person"


11. Columns containing spaces MUST be double quoted.


12. If numeric values are stored as TEXT,
CAST them before mathematical calculations.

Example:

CAST("Actual Price" AS REAL)


13. If numbers contain commas:

CAST(
    REPLACE("Actual Price", ',', '')
    AS REAL
)


14. If values contain ₹:

CAST(
    REPLACE(
        REPLACE("Actual Price", ',', ''),
        '₹',
        ''
    )
    AS REAL
)


15. NEVER generate:

INSERT
UPDATE
DELETE
DROP
ALTER
CREATE
TRUNCATE
REPLACE
PRAGMA
ATTACH
DETACH
VACUUM


16. Correct the query using the SQLite error.

17. Return SQL only.

18. Do NOT return Markdown.

19. Do NOT explain anything.

20. Do NOT return comments.
"""


    user_prompt = f"""
DATABASE SCHEMA:

{schema_context}


USER QUESTION:

{question}


FAILED SQL:

{previous_sql}


SQLITE ERROR:

{sqlite_error}


Repair the SQL and return only the corrected SQLite query.
"""


    result = chat(
        [
            {
                "role": "system",
                "content": system_prompt,
            },
            {
                "role": "user",
                "content": user_prompt,
            },
        ],
        temperature=0,
    )


    result = result.strip()


    # -----------------------------------------------------
    # Clean repaired SQL
    # -----------------------------------------------------

    sql = clean_sql(result)


    print("\n")
    print("=" * 60)
    print("REPAIRED SQL")
    print("=" * 60)

    print(sql)

    print("=" * 60)
    print("\n")


    return sql